    @overload
    def select(self, c1: NullableSelection[Optional, T1], c2: NullableSelection[Optional, T2], /) -> JoinedContext[Root, Required, Optional, tuple[T1 | None, T2 | None], K]: ...
    @overload
    def select(self, c1: Selection[Required, T1] | AggregateSelection[Optional, T1], c2: Selection[Required, T2] | AggregateSelection[Optional, T2], c3: Selection[Required, T3] | AggregateSelection[Optional, T3], /) -> JoinedContext[Root, Required, Optional, tuple[T1, T2, T3], K]: ...
